var info = JSON.parse(java.hexDecodeToString(result));
eval(String(source.variableComment));

base64Url = (i) => {
    return `data:songID;base64,${java.base64Encode(i)},{"type":"qaq"}`;
};
n2s = (num) => {
    if (num > 10000) {
        return `${(num / 10000).toFixed(1)}万`;
    } else {
        return String(num);
    }
};

//单曲
if (info.type == "song") {
    data = JSON.stringify({
        "req_0": {
            "module": "music.trackInfo.UniformRuleCtrl",
            "method": "CgiGetTrackInfo",
            "param": {
                "ids": [info.id], "types": [0]
            }
        },
        "comm": {
            "g_tk": 5381, "uin": 0, "format": "json", "platform": "h5", "deviceToken": "", "deviceId": "", "cv": 0
        }
    });
    songs = zzcSignPost(data).req_0.data.tracks;
    tracks = songs.map(song => ({
        id: song.id,
        name: song.title,
        singer: song.singer.map(singer => singer.name).join(' '),
        time: song.time_public,
        isVip: song.pay.pay_play,
        subtitle: song.subtitle
    }));
    java.put("tracks", JSON.stringify(tracks));
    track = songs[0];
    info = `&nbsp;💿 歌曲：${track.subtitle == '' ? track.name : track.name + ' || ' + track.subtitle}\n🎤 歌手：${track.singer.map(singer => singer.name).join(' ')}\n🏷 发行：${track.time_public}\n🏆 专辑：${track.album.name}\n`;
    result = JSON.stringify({
        name: track.title,
        singer: track.singer.map(singer => singer.name).join(' '),
        kind: [track.album.name, track.subtitle],
